std::vector<int> scores = {42, 10, 99, 5};

// 1. Basic ascending sort on the full range
std::sort(scores.begin(), scores.end());
// scores: {5, 10, 42, 99}

// 2. Custom comparison (Descending order) using a lambda
std::sort(scores.begin(), scores.end(),
    [](int a, int b) {
        return a > b;
    }
);
// scores: {99, 42, 10, 5}

// 3. Sorting a sub-range (middle two elements)
std::sort(scores.begin() + 1, scores.end() - 1);
// scores: {99, 10, 42, 5}
